const body = $('Check webhook').first().json.body;

const existing = $('Get FAQ').first().json.faqs ?? [];
const existingIds = new Set(existing.map((f) => f.id));
const existingTitles = new Set(existing.map((f) => String(f.title).trim()));
const existingKeywords = new Set(existing.flatMap((f) => (f.keywords ?? []).map((k) => String(k).toLowerCase())));
const seen = new Set();
const rows = body.items.map((r) => {
  const errors = [], warnings = [];
  const id = String(r?.id ?? '');
  const title = String(r?.title ?? '').trim();
  const answer = String(r?.answer ?? '').trim();
  if (!/^FAQ-\d{3}$/.test(id)) errors.push('id_format');
  if (!title) errors.push('title_missing'); else if (title.length > 40) errors.push('title_too_long');
  if (!Array.isArray(r?.keywords) || r.keywords.length === 0) errors.push('keywords_missing');
  if (!answer) errors.push('answer_missing'); else if (answer.length < 10) errors.push('answer_too_short'); else if (answer.length > 300) errors.push('answer_too_long');
  if (seen.has(id)) errors.push('duplicate_in_batch');
  seen.add(id);
  if (/01[016789][-. ]?\d{3,4}[-. ]?\d{4}/.test(answer) || /[\w.+-]+@[\w-]+\.[\w.]+/.test(answer)) errors.push('pii');
  if (/https?:\/\/(?!intra\.example\.com(?![\w.-]))/i.test(answer)) errors.push('external_link');

  if (existingIds.has(id)) errors.push('exists_id');
  if (title && existingTitles.has(title)) errors.push('same_title');
  for (const k of (Array.isArray(r?.keywords) ? r.keywords : [])) if (existingKeywords.has(String(k).toLowerCase())) warnings.push(`keyword_used:${k}`);
  return { id, ok: errors.length === 0, errors, warnings };
});
const codes = {};
for (const row of rows) for (const e of row.errors) codes[e] = (codes[e] ?? 0) + 1;
const valid = rows.filter((r) => r.ok).length;
const out = { batch: body.batch ?? '', total: rows.length, valid, invalid: rows.length - valid,
  with_warnings: rows.filter((r) => r.warnings.length).length, rows, codes };

const FIX = {
  id_format: 'id를 FAQ-숫자 3자리로 (예: FAQ-104)',
  title_missing: '제목을 써 주세요',
  title_too_long: '제목을 40자 이내로 줄여 주세요',
  keywords_missing: '키워드를 하나 이상 넣어 주세요',
  answer_missing: '답을 써 주세요',
  answer_too_short: '답을 10자 이상으로 써 주세요',
  answer_too_long: '답을 300자 이내로 줄여 주세요',
  duplicate_in_batch: '같은 배치에 같은 id가 또 있습니다. 하나만 남겨 주세요',
  pii: '개인 전화번호 · 메일 주소를 빼고 IT 포털 안내로 바꿔 주세요',
  external_link: '바깥 링크 대신 사내 주소(intra.example.com)를 써 주세요',
  exists_id: '이미 있는 id입니다. 새 id를 쓰거나, 고치려는 것이면 FAQ 담당자에게 알려 주세요',
  same_title: '같은 제목의 FAQ가 이미 있습니다. 제목을 바꾸거나 기존 FAQ와 합쳐 주세요',
};
out.fix_list = rows.map((r, i) => ({ row: i + 1, id: r.id, codes: r.errors, fix: r.errors.map((e) => FIX[e] ?? e) })).filter((r) => r.codes.length);
out.message = `${out.batch}: ${out.total}줄 중 ${out.valid}줄 통과, ${out.invalid}줄 고칠 것`;
return [{ json: out }];
